    h.T(it.value, { bold: true, color: it.color }),
    h.T(it.label, { dim: true }),
    ...(it.sub || []).map((s) => h.T(s, { color: it.color })),
  ], { color: it.color, key: 'c-' + it.label, grow: true })), { key: 'cg' + i, flexWrap: 'nowrap', gap: 1 }))
}

