      h.T(`${short(p.lead.model)} · ${effortBars(p.lead.effort)} ${p.lead.effort}`, { color: h.famColor(p.lead.model) }),
      h.T(`ctx ${p.lead.ctxPct}%`, { color: p.lead.ctxLevel }),
