    kids.push(h.col([
      h.row([h.T((WL.kinds || {})[r.kind] || r.kind, { color: r.level, bold: true }), h.T(`${WL.since} ${hm(r.since)} (${age(V.at - r.since)})`, { dim: true })]),
      h.T(r.what),
